/**
 * Off-chain biological data storage.
 *
 * §3.5 and §4.3 of the manuscript require that biological payloads never touch
 * the ledger: the payload is encrypted with AES-256, added to IPFS, and only
 * the content identifier plus a key reference are written on-chain.
 *
 * AES-256-GCM is used rather than CBC so that ciphertext integrity is
 * authenticated: a tampered payload fails to decrypt rather than yielding
 * plausible garbage.
 */

import {
  createCipheriv,
  createDecipheriv,
  createHash,
  randomBytes,
  randomUUID,
} from 'crypto';

export const KEY_BYTES = 32; // AES-256
export const IV_BYTES = 12; // GCM standard nonce length

/** Kubo HTTP API endpoints; every node receives a pinned copy. */
export function defaultEndpoints(): string[] {
  return (
    process.env.IPFS_ENDPOINTS ??
    'http://127.0.0.1:5011,http://127.0.0.1:5012,http://127.0.0.1:5013'
  )
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);
}

export interface EncryptedEnvelope {
  ciphertext: Buffer;
  iv: Buffer;
  authTag: Buffer;
}

export interface StoredPayload {
  /** IPFS content identifier of the ciphertext. */
  cid: string;
  /** Opaque handle to the data-encryption key; the key itself stays in the vault. */
  keyRef: string;
  iv: string;
  authTag: string;
  /** SHA-256 of the plaintext, so integrity survives re-encryption. */
  plaintextDigest: string;
  sizeBytes: number;
  /** Endpoints that hold a pinned copy — erasure must reach all of them. */
  pinnedAt: string[];
}

export function encrypt(plaintext: Buffer, key: Buffer): EncryptedEnvelope {
  if (key.length !== KEY_BYTES) throw new Error(`key must be ${KEY_BYTES} bytes (AES-256)`);
  const iv = randomBytes(IV_BYTES);
  const cipher = createCipheriv('aes-256-gcm', key, iv);
  const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  return { ciphertext, iv, authTag: cipher.getAuthTag() };
}

export function decrypt(envelope: EncryptedEnvelope, key: Buffer): Buffer {
  const decipher = createDecipheriv('aes-256-gcm', key, envelope.iv);
  decipher.setAuthTag(envelope.authTag);
  return Buffer.concat([decipher.update(envelope.ciphertext), decipher.final()]);
}

/**
 * Key custody for the prototype.
 *
 * Keys live in process memory and are destroyed by overwriting before release.
 * A production deployment would hold them in an HSM; the manuscript states
 * this as an explicit limitation and the prototype does not claim otherwise.
 * What the prototype does demonstrate is the erasure *mechanism*: once the key
 * is destroyed, the ciphertext is unrecoverable regardless of who holds it.
 */
export class KeyVault {
  private keys = new Map<string, Buffer>();
  private destroyed = new Set<string>();

  /**
   * Mint a key. Only the reference is returned: the vault owns the sole copy
   * of the key material, so `destroy` genuinely destroys it. Handing the
   * buffer out would mean `destroy` wipes a buffer the caller still holds a
   * reference to, corrupting the caller's data while leaving stray copies of
   * the key alive elsewhere.
   */
  create(): { keyRef: string } {
    const keyRef = `key-${randomUUID()}`;
    this.keys.set(keyRef, randomBytes(KEY_BYTES));
    return { keyRef };
  }

  /**
   * The only sanctioned route for key material to leave the vault: producing
   * Shamir recovery shares (§6). Returns a copy, so the vault's own buffer
   * remains the single authoritative one.
   */
  exportForSharing(keyRef: string): Buffer {
    return Buffer.from(this.get(keyRef));
  }

  get(keyRef: string): Buffer {
    const key = this.keys.get(keyRef);
    if (!key) {
      throw new Error(
        this.destroyed.has(keyRef)
          ? `key ${keyRef} was destroyed under GDPR Article 17 and cannot be recovered`
          : `unknown key reference ${keyRef}`,
      );
    }
    return key;
  }

  has(keyRef: string): boolean {
    return this.keys.has(keyRef);
  }

  wasDestroyed(keyRef: string): boolean {
    return this.destroyed.has(keyRef);
  }

  /** Overwrite the key material in place, then drop the reference. */
  destroy(keyRef: string): boolean {
    const key = this.keys.get(keyRef);
    if (!key) return false;
    key.fill(0);
    this.keys.delete(keyRef);
    this.destroyed.add(keyRef);
    return true;
  }

  /** Restore a key recovered from Shamir shares (§6 recovery path). */
  restore(keyRef: string, key: Buffer): void {
    if (key.length !== KEY_BYTES) throw new Error('recovered key has the wrong length');
    this.keys.set(keyRef, key);
    this.destroyed.delete(keyRef);
  }
}

export class IpfsCluster {
  constructor(private endpoints: string[] = defaultEndpoints()) {
    if (this.endpoints.length === 0) throw new Error('no IPFS endpoints configured');
  }

  get nodes(): string[] {
    return [...this.endpoints];
  }

  /**
   * Every call is bounded. Kubo blocks indefinitely on content it does not
   * hold locally, so an unbounded request can hang the caller forever.
   */
  private async post(
    endpoint: string,
    path: string,
    body?: BodyInit,
    timeoutMs = 15000,
  ): Promise<Response> {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    try {
      const res = await fetch(`${endpoint}/api/v0/${path}`, {
        method: 'POST',
        body,
        signal: controller.signal,
      });
      if (!res.ok) {
        throw new Error(`IPFS ${path} at ${endpoint} failed: ${res.status} ${await res.text()}`);
      }
      return res;
    } finally {
      clearTimeout(timer);
    }
  }

  async isReachable(): Promise<boolean> {
    try {
      await this.post(this.endpoints[0], 'id', undefined, 5000);
      return true;
    } catch {
      return false;
    }
  }

  /**
   * Add the ciphertext directly to every node in the cluster.
   *
   * The obvious alternative — add once, then `pin/add` elsewhere — makes the
   * other nodes fetch the block over the DHT, which blocks indefinitely in a
   * private deployment and, worse, would require the cluster to be attached to
   * the public network. Athlete ciphertext must never be announced publicly,
   * so the nodes run with no bootstrap peers and each receives the bytes
   * directly. Content addressing guarantees the CID is identical everywhere,
   * which is asserted rather than assumed.
   */
  async add(data: Buffer): Promise<{ cid: string; pinnedAt: string[] }> {
    const cids: string[] = [];
    const pinnedAt: string[] = [];

    for (const endpoint of this.endpoints) {
      const form = new FormData();
      form.append('file', new Blob([new Uint8Array(data)]), 'payload.bin');
      const res = await this.post(endpoint, 'add?pin=true&cid-version=1', form);
      const { Hash } = (await res.json()) as { Hash: string };
      cids.push(Hash);
      pinnedAt.push(endpoint);
    }

    const unique = new Set(cids);
    if (unique.size !== 1) {
      throw new Error(`IPFS nodes disagreed on the content identifier: ${[...unique].join(', ')}`);
    }
    return { cid: cids[0], pinnedAt };
  }

  async cat(cid: string, timeoutMs = 10000): Promise<Buffer> {
    const res = await this.post(this.endpoints[0], `cat?arg=${cid}`, undefined, timeoutMs);
    return Buffer.from(await res.arrayBuffer());
  }

  /** Whether any node still serves the content, checked locally only. */
  async isRetrievableLocally(cid: string): Promise<boolean> {
    for (const endpoint of this.endpoints) {
      try {
        await this.post(endpoint, `block/stat?arg=${cid}&offline=true`, undefined, 5000);
        return true;
      } catch {
        // this node no longer holds the block
      }
    }
    return false;
  }

  /** Unpin across every node and run garbage collection. */
  async unpinEverywhere(cid: string): Promise<{ endpoint: string; unpinned: boolean }[]> {
    const results: { endpoint: string; unpinned: boolean }[] = [];
    for (const endpoint of this.endpoints) {
      let unpinned = false;
      try {
        await this.post(endpoint, `pin/rm?arg=${cid}&recursive=true`);
        unpinned = true;
      } catch {
        unpinned = false; // already unpinned, or the node never held it
      }
      try {
        await this.post(endpoint, 'repo/gc');
      } catch {
        // GC failure does not affect cryptographic inaccessibility.
      }
      results.push({ endpoint, unpinned });
    }
    return results;
  }
}

export interface StoreOptions {
  cluster: IpfsCluster;
  vault: KeyVault;
}

/** Encrypt, store off-chain, and return exactly what belongs on the ledger. */
export async function storeEncrypted(
  plaintext: Buffer,
  { cluster, vault }: StoreOptions,
): Promise<{ record: StoredPayload }> {
  const { keyRef } = vault.create();
  const envelope = encrypt(plaintext, vault.get(keyRef));
  const { cid, pinnedAt } = await cluster.add(envelope.ciphertext);

  return {
    record: {
      cid,
      keyRef,
      iv: envelope.iv.toString('base64'),
      authTag: envelope.authTag.toString('base64'),
      plaintextDigest: createHash('sha256').update(plaintext).digest('hex'),
      sizeBytes: envelope.ciphertext.length,
      pinnedAt,
    },
  };
}

/** Retrieve and decrypt. Throws if the key was destroyed under Article 17. */
export async function retrieveDecrypted(
  record: StoredPayload,
  { cluster, vault }: StoreOptions,
): Promise<Buffer> {
  const key = vault.get(record.keyRef); // throws once destroyed
  const ciphertext = await cluster.cat(record.cid);
  const plaintext = decrypt(
    {
      ciphertext,
      iv: Buffer.from(record.iv, 'base64'),
      authTag: Buffer.from(record.authTag, 'base64'),
    },
    key,
  );
  const digest = createHash('sha256').update(plaintext).digest('hex');
  if (digest !== record.plaintextDigest) {
    throw new Error('integrity check failed: plaintext digest does not match the ledger record');
  }
  return plaintext;
}

/**
 * GDPR Article 17 cryptographic erasure.
 *
 * Implements the manuscript's `revokeDataAccessKey()` and
 * `destroyIPFSAccessToken()`: the data-encryption key is overwritten and
 * discarded, and the content identifier is unpinned across every IPFS node.
 * The ledger is never rewritten — only the key disappears, which is what makes
 * the scheme compatible with an append-only ledger.
 *
 * HONEST LIMITATION, carried over from the manuscript unchanged: rendering
 * data cryptographically inaccessible has not been confirmed by supervisory
 * authorities to constitute erasure within the meaning of Article 17. This
 * module demonstrates the mechanism; it does not resolve the legal question.
 */

import { IpfsCluster, KeyVault, StoredPayload } from './ipfs-client';
import { Share, combine } from './shamir';

export interface ErasureCertificate {
  cid: string;
  keyRef: string;
  keyDestroyed: boolean;
  unpinResults: { endpoint: string; unpinned: boolean }[];
  /** True only when the key is gone AND no node still pins the content. */
  complete: boolean;
  erasedAt: string;
  legalCaveat: string;
}

const LEGAL_CAVEAT =
  'Cryptographic inaccessibility is not confirmed by supervisory authorities as ' +
  'erasure within the meaning of GDPR Article 17. The mechanism is demonstrated; ' +
  'the legal question remains open.';

/**
 * `revokeDataAccessKey()` — destroy the key alone.
 *
 * Sufficient on its own for inaccessibility: the ciphertext may remain pinned,
 * but without the key it is indistinguishable from random data.
 */
export function revokeDataAccessKey(vault: KeyVault, keyRef: string): boolean {
  return vault.destroy(keyRef);
}

/**
 * `destroyIPFSAccessToken()` — full Article 17 erasure.
 *
 * Destroys the key and unpins the content identifier across the whole cluster,
 * then garbage-collects. Returns a certificate suitable for the audit trail.
 */
export async function destroyIPFSAccessToken(
  record: StoredPayload,
  vault: KeyVault,
  cluster: IpfsCluster,
): Promise<ErasureCertificate> {
  const keyDestroyed = revokeDataAccessKey(vault, record.keyRef);
  const unpinResults = await cluster.unpinEverywhere(record.cid);

  return {
    cid: record.cid,
    keyRef: record.keyRef,
    keyDestroyed,
    unpinResults,
    complete: keyDestroyed && unpinResults.every((r) => r.unpinned),
    erasedAt: new Date().toISOString(),
    legalCaveat: LEGAL_CAVEAT,
  };
}

/**
 * Recover a destroyed key from Shamir shares (§6: any two of athlete,
 * physician, federation official). This is the counterpart to erasure: it
 * exists so that key loss is not irreversible for the athlete themselves,
 * while remaining impossible for any single holder acting alone.
 */
export function recoverDataAccessKey(
  vault: KeyVault,
  keyRef: string,
  shares: Share[],
): Buffer {
  if (shares.length < 2) {
    throw new Error('key recovery requires at least two of the three shares');
  }
  const key = combine(shares);
  vault.restore(keyRef, key);
  return key;
}

/**
 * Shamir secret sharing over GF(2^8), used for 2-of-3 recovery of an athlete's
 * data-encryption key among the athlete, their physician and a federation
 * official (§6 of the implementation plan, §3.5 of the manuscript).
 *
 * Each byte of the secret is shared independently: for a threshold t, a random
 * polynomial of degree t-1 is drawn with the secret byte as constant term, and
 * shares are evaluations of that polynomial at distinct non-zero x values.
 * Recovery is Lagrange interpolation at x = 0.
 *
 * Fewer than t shares yield no information about the secret: for any candidate
 * secret there exists a polynomial consistent with the shares held.
 */

import { randomBytes, timingSafeEqual } from 'crypto';

// GF(2^8) with the AES reduction polynomial x^8 + x^4 + x^3 + x + 1 (0x11b).
const EXP = new Uint8Array(512);
const LOG = new Uint8Array(256);

(function buildTables() {
  let x = 1;
  for (let i = 0; i < 255; i += 1) {
    EXP[i] = x;
    LOG[x] = i;
    // Multiply by the generator 0x03.
    let next = x ^ ((x << 1) & 0xff);
    if (x & 0x80) next ^= 0x1b;
    x = next;
  }
  for (let i = 255; i < 512; i += 1) EXP[i] = EXP[i - 255];
})();

const gfAdd = (a: number, b: number): number => a ^ b;

function gfMul(a: number, b: number): number {
  if (a === 0 || b === 0) return 0;
  return EXP[LOG[a] + LOG[b]];
}

function gfDiv(a: number, b: number): number {
  if (b === 0) throw new Error('division by zero in GF(2^8)');
  if (a === 0) return 0;
  return EXP[LOG[a] + 255 - LOG[b]];
}

export interface Share {
  /** Non-zero x coordinate identifying this share. */
  index: number;
  /** Share bytes, one per secret byte. */
  value: Buffer;
  /** Holder role, recorded for audit; not used in reconstruction. */
  holder?: string;
}

/** Split `secret` into `shares` pieces, any `threshold` of which recover it. */
export function split(secret: Buffer, shares: number, threshold: number): Share[] {
  if (threshold < 2) throw new Error('threshold must be at least 2');
  if (shares < threshold) throw new Error('shares must be at least the threshold');
  if (shares > 255) throw new Error('at most 255 shares are representable in GF(2^8)');
  if (secret.length === 0) throw new Error('secret must be non-empty');

  const out: Share[] = [];
  for (let i = 1; i <= shares; i += 1) {
    out.push({ index: i, value: Buffer.alloc(secret.length) });
  }

  for (let byte = 0; byte < secret.length; byte += 1) {
    // Random polynomial coefficients a_1..a_{t-1}; a_0 is the secret byte.
    const coeffs = randomBytes(threshold - 1);
    for (const share of out) {
      let acc = secret[byte];
      let xPow = 1;
      for (let d = 0; d < threshold - 1; d += 1) {
        xPow = gfMul(xPow, share.index);
        acc = gfAdd(acc, gfMul(coeffs[d], xPow));
      }
      share.value[byte] = acc;
    }
  }
  return out;
}

/** Recover the secret by Lagrange interpolation at x = 0. */
export function combine(shares: Share[]): Buffer {
  if (shares.length < 2) throw new Error('at least two shares are required');
  const indices = shares.map((s) => s.index);
  if (new Set(indices).size !== indices.length) {
    throw new Error('shares must have distinct indices');
  }
  if (indices.some((i) => i === 0)) {
    throw new Error('share index 0 is reserved for the secret itself');
  }
  const length = shares[0].value.length;
  if (shares.some((s) => s.value.length !== length)) {
    throw new Error('shares have inconsistent lengths');
  }

  const secret = Buffer.alloc(length);
  for (let byte = 0; byte < length; byte += 1) {
    let acc = 0;
    for (let i = 0; i < shares.length; i += 1) {
      let numerator = 1;
      let denominator = 1;
      for (let j = 0; j < shares.length; j += 1) {
        if (i === j) continue;
        numerator = gfMul(numerator, shares[j].index);
        denominator = gfMul(denominator, gfAdd(shares[i].index, shares[j].index));
      }
      acc = gfAdd(acc, gfMul(shares[i].value[byte], gfDiv(numerator, denominator)));
    }
    secret[byte] = acc;
  }
  return secret;
}

/**
 * The manuscript's recovery arrangement: three holders, any two of whom can
 * restore the athlete's data-encryption key.
 */
export const RECOVERY_HOLDERS = ['athlete', 'physician', 'federation-official'] as const;
export type RecoveryHolder = (typeof RECOVERY_HOLDERS)[number];

export function splitForRecovery(key: Buffer): Share[] {
  return split(key, 3, 2).map((s, i) => ({ ...s, holder: RECOVERY_HOLDERS[i] }));
}

/** Constant-time equality, so recovery checks do not leak by timing. */
export function secretsEqual(a: Buffer, b: Buffer): boolean {
  return a.length === b.length && timingSafeEqual(a, b);
}
